SELECT jsonb_build_object('project_ref','irjkmhgrjgcaoixcixut','database_name',current_database(),'database_role',current_user,'system_identifier',(SELECT system_identifier::text FROM pg_catalog.pg_control_system()),'rls_tables',(SELECT jsonb_object_agg(schema_name,total) FROM (SELECT n.nspname schema_name,count(c.oid) total FROM pg_catalog.pg_namespace n LEFT JOIN pg_catalog.pg_class c ON c.relnamespace=n.oid AND c.relkind IN ('r','p') AND c.relrowsecurity WHERE n.nspname IN ('public','pos_sync_feed_v1') GROUP BY n.nspname) x),'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'md5',md5(replace(pg_get_functiondef(p.oid),chr(13)||chr(10),chr(10))),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.oid::regprocedure::text) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='public' AND p.proname IN ('booking_handover','reserve_product_skus','received_product_catalogue_stores','pos_sync_push_aggregate')) OR (n.nspname='pos_sync_cash_v1' AND p.proname IN ('assert_extended_tenders','apply_checkout','project_receipt')) OR (n.nspname='pos_sync_feed_v1' AND p.proname IN ('publish_transfer_receipt','record_cash_publication')) OR (n.nspname='private' AND p.proname IN ('check_booking_handover_upload','stock_transfer_receive','stock_transfer_verify'))),'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated) ORDER BY conname) FROM pg_catalog.pg_constraint WHERE conrelid=to_regclass('pos_sync_feed_v1.cash_publications')),'migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version) FROM supabase_migrations.schema_migrations)) AS fingerprint;
